-- Pakistan deep-dive ES/DE/FR translations (completing 374).
-- INSERT OR IGNORE throughout.

-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Clearance en tiempo real mediante API a través del sistema de Facturación Digital de la FBR, implantado por etapas desde 2024 y formalmente completo desde el 31 de diciembre de 2025 -- aunque el cumplimiento real todavía va por detrás del plazo legal', 'Esta página de análisis refleja la orientación pública de la FBR y la información del sector disponible a principios de agosto de 2026, y se ofrece a título informativo general, no como asesoramiento legal o fiscal. Confirme los requisitos vigentes directamente con la FBR o con un asesor fiscal pakistaní antes de basar en esta página sus decisiones de cumplimiento.', 'El mandato de facturación electrónica de Pakistán comenzó como un proyecto piloto restringido al sector de bienes de consumo masivo (FMCG) bajo la SRO 28(I)/2024 y se amplió mediante una cadena de SRO hasta un plazo formal del 31 de diciembre de 2025 que cubre a todas las personas registradas. Un proyecto de SRO de febrero de 2026 propone extender la facturación en tiempo real a una amplia nueva población del sector servicios, pendiente de notificación adicional.', 'Una factura conforme se genera en formato JSON y se envía mediante API -- directamente, a través de un integrador licenciado, o a través de PRAL (Pakistan Revenue Automation Limited, una opción gratuita) -- al sistema de Facturación Digital de la FBR. La FBR valida la factura en tiempo real y devuelve un número de factura único de la FBR más un código QR (ISO/IEC 18004) que codifica el número de factura, el NTN del vendedor, la marca de tiempo, el importe, el impuesto, una URL de verificación y una firma digital, antes de que la factura sea legalmente válida.', 'El mandato se ha ampliado por etapas: un proyecto piloto exclusivo para FMCG (2024), un marco de licencias e integración (principios de 2025), una ampliación a todas las personas registradas, corporativas y no corporativas (mediados de 2025), y un calendario final escalonado que se completó el 31 de diciembre de 2025. A pesar de esa finalización legal, el cumplimiento real en vivo se ha quedado genuinamente rezagado -- vea la tarjeta dedicada más abajo sobre en qué punto se encuentra realmente el cumplimiento, no solo lo que exige la ley.', 'Dado que el cumplimiento real todavía va por detrás del plazo legal, la mayoría de las empresas afectadas tienen trabajo real y actual por hacer -- ya sea completar una primera integración, arreglar un enlace de punto de venta desconectado, o simplemente confirmar que la FBR ahora aprueba sus facturas en tiempo real en lugar de depender de un antiguo proceso posterior a la creación.', 'Pakistán respalda su mandato de facturación digital con sanciones reales y documentadas conforme al artículo 33 de la Ley del Impuesto sobre las Ventas -- no con las cifras sin fuente de "500k/1M/2M/3M" que a veces se citan en línea -- que van desde multas de seis cifras hasta el precinto de locales y responsabilidad penal para las infracciones más graves.', 'Pakistán exige el clearance en tiempo real mediante API de las facturas del impuesto sobre las ventas a través del sistema de Facturación Digital de la FBR, gestionado directamente, a través de un integrador licenciado, o a través de PRAL. El despliegue formal -- desde un proyecto piloto de FMCG en 2024 hasta un plazo del 31 de diciembre de 2025 que cubre a todas las personas registradas -- está completo sobre el papel, pero el cumplimiento real ha quedado muy por detrás: los propios funcionarios de la FBR seguían informando de un gran número de contribuyentes no integrados bien entrado mediados de 2026, y el resultado de una nueva ofensiva de aplicación todavía no está confirmado.', '🇵🇰' FROM countries WHERE name_en = 'Pakistan';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '31 dic 2025', 'Plazo formal para que todas las personas registradas se integren' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Pakistan' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '~1 de cada 3', 'Contribuyentes registrados que emiten facturas digitales en vivo, finales de marzo de 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Pakistan' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '27-32%', 'De ~37.000 sucursales minoristas con TPV integrado que seguían desconectadas, junio de 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Pakistan' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '500.000 Rs o 200%', 'Sanción por no integrarse (artículo 33, apartado 24)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Pakistan' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '18 feb 2026', 'El proyecto de SRO 288(I)/2026 propone la expansión al sector servicios' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Pakistan' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Formato y transmisión', '[["Formato de factura", "JSON, enviado mediante API (no XML)"], ["Canales de acceso", "Integración API directa, un integrador licenciado, o PRAL (Pakistan Revenue Automation Limited, gratuito)"], ["Validación", "En tiempo real por el sistema de Facturación Digital de la FBR antes de que la factura sea legalmente válida"], ["Confirmación", "Un número de factura único de la FBR más un código QR, devueltos por la FBR al aprobarse"]]', 'Las facturas sin clearance no son legalmente válidas y bloquean la reclamación del crédito fiscal del comprador -- trate el clearance de la FBR como un requisito previo estricto, no como una formalidad posterior.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Código QR y contenido de la factura', '[["Estándar QR", "ISO/IEC 18004"], ["Contenido del QR", "Número de factura de la FBR, NTN del vendedor, marca de tiempo, importe, impuesto, una URL de verificación y una firma digital"], ["Conservación de registros", "6 años"], ["Ventana de autocorrección", "72 horas (Orden General del Impuesto sobre las Ventas 01 de 2026); a partir de entonces se requiere la aprobación del Comisionado de Ingresos Internos"]]', 'La ventana de autocorrección de 72 horas es nueva desde marzo de 2026 -- confirme que su equipo de facturación conoce la norma vigente en lugar de una suposición más antigua, más estricta o más laxa.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Gestión de interrupciones y base legal', '[["Respaldo sin conexión", "Las facturas emitidas durante una interrupción confirmada del sistema deben cargarse en las 24 horas siguientes a su restablecimiento"], ["Base legal", "Ley del Impuesto sobre las Ventas de 1990, artículos 3(9A) y 40C; Normas del Impuesto sobre las Ventas de 2006, Capítulo XIV"], ["Marco sancionador", "Ley del Impuesto sobre las Ventas de 1990, artículo 33"], ["Consecuencia de no obtener el clearance", "La factura es legalmente inválida; el comprador no puede reclamar el crédito fiscal sobre ella"]]', 'La ventana de 24 horas para cargas sin conexión está pensada para interrupciones genuinas y confirmadas -- la postura de aplicación de la FBR la trata como una excepción estrecha, no como una solución habitual para una incorporación lenta.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo de clearance', 'Una factura recorre esta secuencia bajo el sistema de Facturación Digital de la FBR -- la validación de la FBR ocurre antes de que la factura sea legalmente válida, no después:', 'Se trata de un auténtico modelo de clearance: una factura no tiene efecto legal -- ni puede sustentar el crédito fiscal del comprador -- hasta que la FBR devuelve un número de factura y un código QR válidos.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'El vendedor genera la factura en formato JSON' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'La factura se envía mediante API, un integrador licenciado, o PRAL' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'La FBR valida la factura en tiempo real' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'La FBR devuelve un número de factura único y un código QR' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'La factura es legalmente válida y se entrega al comprador -- solo entonces puede sustentar el crédito fiscal del comprador' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Lo que exige la ley', '[["SRO 28(I)/2024", "Proyecto piloto del sector FMCG (1 de febrero de 2024) -- el origen del mandato"], ["SRO 69(I)/2025", "Marco de licencias e integración del Capítulo XIV (29 de enero de 2025) -- fundacional, no amplía el alcance"], ["SRO 709(I)/2025", "Ampliado a todas las personas registradas, corporativas y no corporativas (22 de abril de 2025), con dos prórrogas mensuales posteriores"], ["SRO 1852(I)/2025", "Calendario final vigente: olas el 1 de nov., 15 de nov., 1 de dic. y 31 de dic. de 2025 (24 de septiembre de 2025)"]]', 'Esta es la cronología legal, no la realidad del cumplimiento -- vea la siguiente tarjeta para saber cómo se compara realmente la adopción en vivo con este calendario.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'En qué punto se encuentra realmente el cumplimiento', NULL, NULL, 'A pesar del plazo formal del 31 de diciembre de 2025, el cumplimiento real se ha quedado muy rezagado. El propio Miembro para la Transformación Estratégica de la FBR, el Dr. Hamid Ateeq Sarwar, declaró directamente que solo alrededor de un tercio de los contribuyentes registrados emitía facturas digitales en vivo a finales de marzo de 2026. Incluso según la métrica más antigua y estrecha de los puntos de venta (TPV) de Nivel 1, entre el 27% y el 32% de las aproximadamente 37.000 sucursales minoristas integradas seguían desconectadas en junio de 2026. La FBR solo comenzó una aplicación seria -- procedimientos sancionadores a importadores, suspensión de registro, retirada del canal verde aduanero -- a partir del 1 de julio de 2026, con el objetivo de lograr la adopción plena para el 31 de julio de 2026. Según la investigación más reciente (5 de agosto de 2026), no existe confirmación en ningún sentido de si ese objetivo se cumplió realmente. Trate el mandato como legalmente completo pero, en la práctica, todavía en proceso de converger hacia el pleno cumplimiento, no como un hecho consumado sobre el terreno.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '⚠️ No integrarse conlleva la sanción más severa', NULL, NULL, 'Conforme al artículo 33, apartado 24, de la Ley del Impuesto sobre las Ventas de 1990, no integrarse a efectos de supervisión o seguimiento conlleva una multa de 500.000 Rs o el 200% del impuesto involucrado, lo que sea mayor, con responsabilidad penal opcional de hasta 2 años de prisión o una multa de hasta 2.000.000 Rs. Esta es la mayor exposición financiera individual dentro del marco sancionador de facturación electrónica de Pakistán.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🔒 El fallo de registro puede acabar en el precinto de locales', NULL, NULL, 'El artículo 33, apartado 25, fija una sanción de hasta 1.000.000 Rs por no registrarse o no integrarse en absoluto, con la consecuencia adicional de que la FBR puede precintar los locales de una empresa si la infracción continúa 6 meses después de imponerse la sanción. El apartado 25AA (añadido por la Ley de Finanzas de 2024) aplica la misma lógica a los propios integradores licenciados: un integrador que no logre integrar a una persona registrada se enfrenta a 1.000.000 Rs o al 1% del valor de las ventas ocultadas, lo que sea mayor.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '📈 Reincidencia y el alcance cada vez mayor del mandato', NULL, NULL, 'El artículo 33(21) duplica la sanción aplicable a los reincidentes, y la Ley de Finanzas de 2025 amplió estas disposiciones de aplicación de los minoristas de Nivel 1 exclusivamente a todas las personas registradas -- una ampliación real de a quién pueden aplicarse estas sanciones. Más allá de las multas, el incumplimiento puede desencadenar el precinto de locales, la suspensión o inclusión en lista negra del registro del impuesto sobre las ventas, la retirada del canal verde aduanero para importadores (una nueva palanca introducida con la ofensiva del 1 de julio de 2026), y el enjuiciamiento penal en casos de fraude.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'penalties_related' AND cd.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '❓ Una escala de sanciones muy citada no se sostiene', NULL, NULL, 'Parte del contenido de proveedores y asesores hace circular una ordenada escala de sanciones crecientes de "500.000 Rs / 1 millón de Rs / 2 millones de Rs / 3 millones de Rs" por incumplimiento de la facturación electrónica. Ese conjunto de cifras no pudo rastrearse hasta una sola disposición legal y parece una conflación o una atribución errónea más que una lectura precisa de la ley. Las filas de sanciones que figuran a continuación reflejan lo que dicen realmente las disposiciones documentadas del artículo 33 -- use esas, no la escala de cifras redondas, al evaluar la exposición real.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'penalties_related' AND cd.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'No integrarse a efectos de supervisión/seguimiento (artículo 33, apartado 24)', '500.000 Rs o el 200% del impuesto involucrado, lo que sea mayor; prisión opcional de hasta 2 años o multa de hasta 2.000.000 Rs', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Pakistan' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'No registrarse ni integrarse en absoluto (artículo 33, apartado 25)', 'Hasta 1.000.000 Rs; los locales pueden precintarse si la infracción continúa 6 meses después de la sanción', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Pakistan' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Un integrador licenciado no logra integrar a una persona registrada (artículo 33, apartado 25AA, añadido por la Ley de Finanzas de 2024)', '1.000.000 Rs o el 1% del valor de las ventas ocultadas, lo que sea mayor', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Pakistan' AND pr.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme su estado de registro y qué ola de la SRO 1852(I)/2025 le corresponde', 'Compruebe si su empresa es una sociedad cotizada, un importador, tiene un volumen de negocio superior a 1.000 millones de rupias, suministra a entidades gubernamentales, o entra en una de las olas posteriores -- la ola en la que se encuentre determina cuándo comenzó su obligación.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Elija una vía de integración: API directa, un integrador licenciado, o PRAL', 'PRAL (Pakistan Revenue Automation Limited) ofrece una opción de integración gratuita -- sopésela frente a un integrador licenciado o una construcción de API directa según sus sistemas y volumen actuales.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Construya su sistema de facturación para generar JSON y enviarlo a validación en tiempo real de la FBR', 'Confirme que su software de facturación realmente produce una carga JSON conforme y llama a la API de Facturación Digital de la FBR, en lugar de depender de un proceso manual o por lotes.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Trate el número de factura y el código QR devueltos por la FBR como el punto de validez legal', 'Una factura sin el número y el código QR devueltos por la FBR no es legalmente válida y no puede sustentar el crédito fiscal del comprador -- no trate el mero envío como si fuera la finalización del proceso.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Construya un proceso genuino de respaldo de 24 horas ante interrupciones y de autocorrección de 72 horas', 'Mantenga ambos estrictamente limitados a interrupciones reales del sistema y a necesidades de corrección genuinas -- la postura de aplicación de la FBR trata la dependencia habitual de cualquiera de los dos como una señal de alerta de cumplimiento, no como un hábito seguro.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Siga el proyecto de SRO 288(I)/2026 si su empresa es un restaurante, una clínica, un salón, una mensajería, una firma contable, una escuela, un gimnasio o similar', 'El proyecto todavía no es legalmente vinculante -- esté atento a la orden general del impuesto sobre la renta de seguimiento que realmente lo pondría en vigor, en lugar de actuar como si el propio proyecto ya fuera exigible hoy.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Facturación Digital de la FBR — asistencia técnica, orientación de integración y acceso al portal IRIS' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Pakistan' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Junta Federal de Ingresos (FBR) — sitio general, SRO y notificaciones regulatorias' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Pakistan' AND pt.sort_order = 1;

-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Echtzeit-API-Freigabe über das Digital-Invoicing-System der FBR, seit 2024 stufenweise eingeführt und seit dem 31. Dezember 2025 formal abgeschlossen -- die tatsächliche Einhaltung hinkt der gesetzlichen Frist jedoch weiterhin hinterher', 'Diese Analyseseite spiegelt öffentlich verfügbare Hinweise der FBR und Brancheninformationen mit Stand Anfang August 2026 wider und dient allgemeinen Informationszwecken, nicht als Rechts- oder Steuerberatung. Bestätigen Sie aktuelle Anforderungen direkt bei der FBR oder einem pakistanischen Steuerberater, bevor Sie sich bei Compliance-Entscheidungen auf diese Seite verlassen.', 'Pakistans E-Rechnungspflicht begann als eng begrenztes Pilotprojekt für den FMCG-Sektor unter der SRO 28(I)/2024 und wurde über eine Kette von SROs bis zu einer formalen Frist am 31. Dezember 2025 ausgeweitet, die alle registrierten Personen erfasst. Ein Entwurf der SRO vom Februar 2026 schlägt vor, die Echtzeit-Rechnungsstellung auf eine breite neue Dienstleistungssektor-Population auszuweiten, vorbehaltlich einer weiteren Bekanntmachung.', 'Eine konforme Rechnung wird als JSON erstellt und per API -- direkt, über einen lizenzierten Integrator oder über PRAL (Pakistan Revenue Automation Limited, eine kostenlose Option) -- an das Digital-Invoicing-System der FBR übermittelt. Die FBR validiert die Rechnung in Echtzeit und gibt eine eindeutige FBR-Rechnungsnummer sowie einen QR-Code (ISO/IEC 18004) zurück, der Rechnungsnummer, Verkäufer-NTN, Zeitstempel, Betrag, Steuer, eine Prüf-URL und eine digitale Signatur enthält, bevor die Rechnung rechtsgültig ist.', 'Die Pflicht wurde stufenweise ausgeweitet: ein reines FMCG-Pilotprojekt (2024), ein Lizenzierungs-/Integrationsrahmenwerk (Anfang 2025), eine Ausweitung auf alle körperschaftlichen und nicht-körperschaftlichen registrierten Personen (Mitte 2025) und ein abschließender gestaffelter Zeitplan, der am 31. Dezember 2025 abgeschlossen wurde. Trotz dieses rechtlichen Abschlusses hinkt die tatsächliche Live-Einhaltung spürbar hinterher -- siehe die eigene Karte weiter unten dazu, wo die Einhaltung tatsächlich steht, nicht nur, was das Gesetz verlangt.', 'Da die tatsächliche Einhaltung der gesetzlichen Frist weiterhin hinterherhinkt, haben die meisten betroffenen Unternehmen noch reale, aktuelle Arbeit vor sich -- sei es der Abschluss einer ersten Integration, die Behebung einer getrennten Kassenverbindung, oder einfach die Bestätigung, dass die FBR ihre Rechnungen jetzt in Echtzeit freigibt, statt sich auf einen alten nachträglichen Prozess zu verlassen.', 'Pakistan untermauert seine Digital-Invoicing-Pflicht mit realen, belegten Sanktionen nach Abschnitt 33 des Umsatzsteuergesetzes -- nicht mit den unbelegten „500k/1M/2M/3M"-Zahlen, die online gelegentlich zitiert werden -- die von sechsstelligen Bußgeldern bis zur Versiegelung von Geschäftsräumen und strafrechtlicher Haftung für die schwerwiegendsten Verstöße reichen.', 'Pakistan verlangt eine Echtzeit-API-Freigabe von Umsatzsteuerrechnungen über das Digital-Invoicing-System der FBR, betrieben direkt, über einen lizenzierten Integrator oder über PRAL. Der formale Rollout -- von einem FMCG-Pilotprojekt 2024 bis zu einer Frist am 31. Dezember 2025, die alle registrierten Personen erfasst -- ist auf dem Papier abgeschlossen, doch die tatsächliche Einhaltung liegt deutlich dahinter zurück: Die eigenen Vertreter der FBR meldeten noch bis weit ins Jahr 2026 hinein eine große Zahl nicht integrierter Steuerpflichtiger, und das Ergebnis einer neuen Durchsetzungsoffensive ist noch nicht bestätigt.', '🇵🇰' FROM countries WHERE name_en = 'Pakistan';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '31. Dez. 2025', 'Formale Frist für alle registrierten Personen zur Integration' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Pakistan' AND s.sort_order = 0;
