INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '27-32%', 'Von ~37.000 integrierten POS-Einzelhandelsfilialen weiterhin nicht angeschlossen, Juni 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Pakistan' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '500.000 Rs oder 200%', 'Strafe für Nicht-Integration (Abschnitt 33, Nr. 24)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Pakistan' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '18. Feb. 2026', 'Entwurf der SRO 288(I)/2026 schlägt Ausweitung auf den Dienstleistungssektor vor' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Pakistan' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Format & Übermittlung', '[["Rechnungsformat", "JSON, übermittelt per API (kein XML)"], ["Zugangskanäle", "Direkte API-Integration, ein lizenzierter Integrator, oder PRAL (Pakistan Revenue Automation Limited, kostenlos)"], ["Validierung", "Echtzeit durch das Digital-Invoicing-System der FBR, bevor die Rechnung rechtsgültig ist"], ["Bestätigung", "Eine eindeutige FBR-Rechnungsnummer plus ein QR-Code, von der FBR bei Genehmigung zurückgegeben"]]', 'Nicht freigegebene Rechnungen sind rechtlich ungültig und blockieren den Vorsteuerabzug des Käufers -- betrachten Sie die FBR-Freigabe als harte Voraussetzung, nicht als nachträgliche Formalität.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'QR-Code & Rechnungsinhalt', '[["QR-Standard", "ISO/IEC 18004"], ["QR-Inhalt", "FBR-Rechnungsnummer, Verkäufer-NTN, Zeitstempel, Betrag, Steuer, eine Prüf-URL und eine digitale Signatur"], ["Aufbewahrung", "6 Jahre"], ["Selbstkorrekturfenster", "72 Stunden (Umsatzsteuer-Generalerlass 01 von 2026); danach ist die Genehmigung des Commissioner of Inland Revenue erforderlich"]]', 'Das 72-Stunden-Selbstkorrekturfenster gilt erst seit März 2026 -- prüfen Sie, ob Ihr Rechnungsteam die aktuelle Regel kennt und nicht von einer älteren, strengeren oder lockereren Annahme ausgeht.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Umgang mit Ausfällen & Rechtsgrundlage', '[["Offline-Rückfalllösung", "Während eines bestätigten Systemausfalls ausgestellte Rechnungen müssen innerhalb von 24 Stunden nach Wiederherstellung hochgeladen werden"], ["Rechtsgrundlage", "Umsatzsteuergesetz 1990, Abschnitte 3(9A) und 40C; Umsatzsteuervorschriften 2006, Kapitel XIV"], ["Sanktionsrahmen", "Umsatzsteuergesetz 1990, Abschnitt 33"], ["Folge fehlender Freigabe", "Die Rechnung ist rechtlich ungültig; der Käufer kann keinen Vorsteuerabzug dafür geltend machen"]]', 'Das 24-Stunden-Fenster für Offline-Uploads ist für echte, bestätigte Ausfälle gedacht -- die Durchsetzungspraxis der FBR behandelt es als eng begrenzte Ausnahme, nicht als routinemäßige Umgehung für ein langsames Onboarding.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der Freigabeablauf', 'Eine Rechnung durchläuft unter dem Digital-Invoicing-System der FBR diese Abfolge -- die FBR-Validierung erfolgt vor, nicht nach der Rechtsgültigkeit der Rechnung:', 'Dies ist ein echtes Freigabemodell: Eine Rechnung hat keine Rechtswirkung -- und kann den Vorsteuerabzug des Käufers nicht stützen --, bis die FBR eine gültige Rechnungsnummer und einen QR-Code zurückgibt.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Der Verkäufer erstellt die Rechnung als JSON' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Die Rechnung wird per API, über einen lizenzierten Integrator oder über PRAL übermittelt' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Die FBR validiert die Rechnung in Echtzeit' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Die FBR gibt eine eindeutige Rechnungsnummer und einen QR-Code zurück' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Die Rechnung ist rechtsgültig und wird an den Käufer ausgeliefert -- erst jetzt kann sie den Vorsteuerabzug des Käufers stützen' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Was das Gesetz verlangt', '[["SRO 28(I)/2024", "FMCG-Sektor-Pilotprojekt (1. Februar 2024) -- der Ursprung der Pflicht"], ["SRO 69(I)/2025", "Lizenzierungs-/Integrationsrahmenwerk nach Kapitel XIV (29. Januar 2025) -- grundlegend, keine Erweiterung des Anwendungsbereichs"], ["SRO 709(I)/2025", "Ausgeweitet auf alle körperschaftlichen und nicht-körperschaftlichen registrierten Personen (22. April 2025), mit zwei späteren einmonatigen Fristverlängerungen"], ["SRO 1852(I)/2025", "Endgültiger maßgeblicher Zeitplan: Wellen am 1. Nov., 15. Nov., 1. Dez. und 31. Dez. 2025 (24. September 2025)"]]', 'Dies ist der rechtliche Zeitplan, nicht die Compliance-Realität -- siehe die nächste Karte dazu, wie die tatsächliche Einführung mit diesem Zeitplan tatsächlich vergleichbar ist.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Wo die tatsächliche Einhaltung tatsächlich steht', NULL, NULL, 'Trotz der formalen Frist vom 31. Dezember 2025 hinkt die tatsächliche Einhaltung deutlich hinterher. Das für strategische Transformation zuständige Mitglied der FBR, Dr. Hamid Ateeq Sarwar, erklärte direkt, dass Ende März 2026 nur rund ein Drittel der registrierten Steuerpflichtigen tatsächlich Live-Digitalrechnungen ausstellte. Selbst nach der älteren, engeren Tier-1-Kassenkennzahl waren im Juni 2026 noch 27-32 % der rund 37.000 integrierten Einzelhandelsfilialen nicht angeschlossen. Die FBR begann erst ab dem 1. Juli 2026 mit ernsthafter Durchsetzung -- Bußgeldverfahren gegen Importeure, Aussetzung der Registrierung, Entzug des Zoll-Grünkanals -- mit dem Ziel, bis zum 31. Juli 2026 volle Compliance zu erreichen. Nach dem Stand der jüngsten Recherche (5. August 2026) gibt es keine Bestätigung in die eine oder andere Richtung, ob dieses Ziel tatsächlich erreicht wurde. Betrachten Sie die Pflicht als rechtlich abgeschlossen, aber praktisch noch auf dem Weg zur vollständigen Einhaltung, nicht als feststehende Tatsache vor Ort.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '⚠️ Nicht-Integration zieht die schärfste Strafe nach sich', NULL, NULL, 'Nach Abschnitt 33, Nr. 24 des Umsatzsteuergesetzes 1990 zieht die Nicht-Integration zu Überwachungs- oder Nachverfolgungszwecken ein Bußgeld von 500.000 Rs oder 200 % der betroffenen Steuer nach sich, je nachdem, was höher ist, mit optionaler strafrechtlicher Haftung von bis zu 2 Jahren Haft oder einem Bußgeld von bis zu 2.000.000 Rs. Dies ist das größte einzelne finanzielle Risiko im pakistanischen Sanktionsrahmen für E-Rechnungen.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🔒 Ein Registrierungsversäumnis kann zur Versiegelung der Geschäftsräume führen', NULL, NULL, 'Abschnitt 33, Nr. 25 legt eine Strafe von bis zu 1.000.000 Rs fest, wenn eine Registrierung oder Integration überhaupt unterbleibt, mit der zusätzlichen Folge, dass die FBR die Geschäftsräume eines Unternehmens versiegeln kann, wenn der Verstoß 6 Monate nach Verhängung der Strafe fortbesteht. Nr. 25AA (eingeführt durch das Finanzgesetz 2024) wendet dieselbe Logik auf lizenzierte Integratoren selbst an: Ein Integrator, der eine registrierte Person nicht integriert, sieht sich 1.000.000 Rs oder 1 % des unterschlagenen Umsatzwerts gegenüber, je nachdem, was höher ist.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '📈 Wiederholungstäter und die wachsende Reichweite der Pflicht', NULL, NULL, 'Abschnitt 33(21) verdoppelt die geltende Strafe für Wiederholungstäter, und das Finanzgesetz 2025 weitete diese Durchsetzungsbestimmungen von ausschließlich Tier-1-Einzelhändlern auf alle registrierten Personen aus -- eine echte Erweiterung, für wen diese Strafen gelten können. Über Bußgelder hinaus kann Nichteinhaltung zur Versiegelung von Geschäftsräumen, zur Aussetzung oder Blacklistung der Umsatzsteuerregistrierung, zum Entzug des Zoll-Grünkanals für Importeure (ein neues Instrument, eingeführt mit der Durchsetzungsoffensive vom 1. Juli 2026) und zu strafrechtlicher Verfolgung in Betrugsfällen führen.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'penalties_related' AND cd.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '❓ Eine oft zitierte Strafenskala hält nicht stand', NULL, NULL, 'In manchen Anbieter- und Beratungsinhalten kursiert eine ordentliche, ansteigende Strafenskala von „500.000 Rs / 1 Million Rs / 2 Millionen Rs / 3 Millionen Rs" für die Nichteinhaltung der E-Rechnungspflicht. Dieser Zahlensatz ließ sich nicht auf eine einzelne gesetzliche Bestimmung zurückführen und wirkt eher wie eine Vermengung oder Fehlzuschreibung als eine genaue Lesart des Gesetzes. Die untenstehenden Strafzeilen geben wieder, was die tatsächlichen, belegten Bestimmungen des Abschnitts 33 tatsächlich besagen -- nutzen Sie diese, nicht die runde Zahlenskala, um das reale Risiko einzuschätzen.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'penalties_related' AND cd.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Nicht-Integration zu Überwachungs-/Nachverfolgungszwecken (Abschnitt 33, Nr. 24)', '500.000 Rs oder 200 % der betroffenen Steuer, je nachdem, was höher ist; optionale Haft bis zu 2 Jahren oder Bußgeld bis zu 2.000.000 Rs', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Pakistan' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Keine Registrierung oder Integration überhaupt (Abschnitt 33, Nr. 25)', 'Bis zu 1.000.000 Rs; Geschäftsräume können versiegelt werden, wenn der Verstoß 6 Monate nach der Strafe fortbesteht', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Pakistan' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Lizenzierter Integrator integriert eine registrierte Person nicht (Abschnitt 33, Nr. 25AA, eingeführt durch das Finanzgesetz 2024)', '1.000.000 Rs oder 1 % des unterschlagenen Umsatzwerts, je nachdem, was höher ist', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Pakistan' AND pr.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bestätigen Sie Ihren Registrierungsstatus und welche SRO-1852(I)/2025-Welle für Sie gilt', 'Prüfen Sie, ob Ihr Unternehmen eine börsennotierte Gesellschaft, ein Importeur ist, einen Umsatz über 1 Milliarde Rupien hat, öffentliche Stellen beliefert oder in eine der späteren Wellen fällt -- die Welle, in der Sie sich befinden, bestimmt, wann Ihre Pflicht begann.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Wählen Sie einen Integrationsweg: direkte API, ein lizenzierter Integrator, oder PRAL', 'PRAL (Pakistan Revenue Automation Limited) bietet eine kostenlose Integrationsoption -- wägen Sie diese gegen einen lizenzierten Integrator oder eine direkte API-Entwicklung anhand Ihrer bestehenden Systeme und Ihres Volumens ab.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bauen Sie Ihr Rechnungssystem so, dass es JSON erzeugt und zur Echtzeit-FBR-Validierung übermittelt', 'Stellen Sie sicher, dass Ihre Rechnungssoftware tatsächlich eine konforme JSON-Nutzlast erzeugt und die Digital-Invoicing-API der FBR aufruft, statt sich auf einen manuellen oder Batch-Prozess zu verlassen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Behandeln Sie die von der FBR zurückgegebene Rechnungsnummer und den QR-Code als den Zeitpunkt der Rechtsgültigkeit', 'Eine Rechnung ohne die von der FBR zurückgegebene Nummer und den QR-Code ist rechtlich ungültig und kann den Vorsteuerabzug des Käufers nicht stützen -- betrachten Sie die bloße Übermittlung nicht als Abschluss.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bauen Sie einen echten 24-Stunden-Ausfall-Rückfallprozess und ein 72-Stunden-Selbstkorrekturverfahren auf', 'Beschränken Sie beides eng auf tatsächliche Systemausfälle und echten Korrekturbedarf -- die Durchsetzungspraxis der FBR behandelt eine routinemäßige Abhängigkeit von beidem als Compliance-Warnsignal, nicht als sichere Gewohnheit.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Verfolgen Sie den Entwurf der SRO 288(I)/2026, wenn Ihr Unternehmen ein Restaurant, eine Klinik, ein Salon, ein Kurierdienst, eine Steuerberatungsfirma, eine Schule, ein Fitnessstudio oder Ähnliches ist', 'Der Entwurf ist noch nicht rechtsverbindlich -- achten Sie auf den folgenden Einkommensteuer-Generalerlass, der ihn tatsächlich in Kraft setzen würde, statt so zu handeln, als sei der Entwurf selbst bereits heute durchsetzbar.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'FBR Digital Invoicing — technische Unterstützung, Integrationsanleitung und Zugang zum IRIS-Portal' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Pakistan' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Federal Board of Revenue (FBR) — allgemeine Website, SROs und behördliche Bekanntmachungen' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Pakistan' AND pt.sort_order = 1;

-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Dédouanement en temps réel via API par le système de facturation numérique de la FBR, déployé par étapes depuis 2024 et formellement achevé depuis le 31 décembre 2025 -- bien que la conformité réelle accuse toujours du retard sur l''échéance légale', 'Cette page d''analyse reflète les indications publiques de la FBR et les informations sectorielles disponibles début août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Confirmez les exigences actuelles directement auprès de la FBR ou d''un conseiller fiscal pakistanais avant de fonder vos décisions de conformité sur cette page.', 'L''obligation de facturation électronique du Pakistan a débuté comme un projet pilote restreint au secteur des biens de grande consommation (FMCG) sous la SRO 28(I)/2024 et s''est étendue via une chaîne de SRO jusqu''à une échéance formelle du 31 décembre 2025 couvrant toutes les personnes enregistrées. Un projet de SRO de février 2026 propose d''étendre la facturation en temps réel à une large nouvelle population du secteur des services, en attente d''une notification supplémentaire.', 'Une facture conforme est générée au format JSON et soumise via API -- directement, via un intégrateur agréé, ou via PRAL (Pakistan Revenue Automation Limited, une option gratuite) -- au système de facturation numérique de la FBR. La FBR valide la facture en temps réel et renvoie un numéro de facture FBR unique ainsi qu''un code QR (ISO/IEC 18004) codant le numéro de facture, le NTN du vendeur, l''horodatage, le montant, la taxe, une URL de vérification et une signature numérique, avant que la facture ne soit juridiquement valable.', 'L''obligation s''est étendue par étapes : un projet pilote réservé aux FMCG (2024), un cadre d''agrément et d''intégration (début 2025), une extension à toutes les personnes enregistrées, morales et non morales (mi-2025), et un calendrier échelonné final achevé le 31 décembre 2025. Malgré cet achèvement légal, la conformité réelle sur le terrain a véritablement pris du retard -- voir la carte dédiée ci-dessous sur où en est réellement la conformité, pas seulement ce que la loi exige.', 'La conformité réelle accusant toujours du retard sur l''échéance légale, la plupart des entreprises concernées ont encore un véritable travail actuel à accomplir -- qu''il s''agisse d''achever une première intégration, de réparer un lien de point de vente déconnecté, ou simplement de confirmer que la FBR dédouane désormais leurs factures en temps réel plutôt que de s''appuyer sur un ancien processus a posteriori.', 'Le Pakistan appuie son obligation de facturation numérique sur des sanctions réelles et documentées prévues par l''article 33 de la loi sur la taxe sur les ventes -- et non sur les chiffres non sourcés « 500k/1M/2M/3M » parfois cités en ligne -- allant d''amendes à six chiffres à la mise sous scellés des locaux et à une responsabilité pénale pour les manquements les plus graves.', 'Le Pakistan exige un dédouanement en temps réel via API des factures de taxe sur les ventes par le système de facturation numérique de la FBR, exploité directement, via un intégrateur agréé, ou via PRAL. Le déploiement formel -- d''un projet pilote FMCG en 2024 à une échéance du 31 décembre 2025 couvrant toutes les personnes enregistrées -- est achevé sur le papier, mais la conformité réelle a pris un retard considérable : les propres responsables de la FBR signalaient encore un grand nombre de contribuables non intégrés bien après la mi-2026, l''issue d''une nouvelle offensive de contrôle n''étant pas encore confirmée.', '🇵🇰' FROM countries WHERE name_en = 'Pakistan';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '31 déc. 2025', 'Échéance formelle pour l''intégration de toutes les personnes enregistrées' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Pakistan' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '~1 sur 3', 'Contribuables enregistrés émettant des factures numériques en direct, fin mars 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Pakistan' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '27-32%', 'Sur ~37 000 succursales de détail à TPV intégré, encore déconnectées, juin 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Pakistan' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '500 000 Rs ou 200 %', 'Sanction pour non-intégration (article 33, point 24)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Pakistan' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '18 févr. 2026', 'Le projet de SRO 288(I)/2026 propose une extension au secteur des services' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Pakistan' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format et transmission', '[["Format de facture", "JSON, soumis via API (pas de XML)"], ["Canaux d''accès", "Intégration API directe, un intégrateur agréé, ou PRAL (Pakistan Revenue Automation Limited, gratuit)"], ["Validation", "En temps réel par le système de facturation numérique de la FBR avant que la facture soit juridiquement valable"], ["Confirmation", "Un numéro de facture FBR unique accompagné d''un code QR, renvoyés par la FBR lors de l''approbation"]]', 'Les factures non dédouanées sont juridiquement invalides et bloquent la réclamation du crédit de taxe en amont de l''acheteur -- considérez le dédouanement de la FBR comme une condition préalable stricte, non comme une formalité a posteriori.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Code QR et contenu de la facture', '[["Norme QR", "ISO/IEC 18004"], ["Contenu du QR", "Numéro de facture FBR, NTN du vendeur, horodatage, montant, taxe, une URL de vérification et une signature numérique"], ["Conservation des documents", "6 ans"], ["Fenêtre d''autocorrection", "72 heures (arrêté général de la taxe sur les ventes n° 01 de 2026) ; l''approbation du Commissioner of Inland Revenue est requise au-delà"]]', 'La fenêtre d''autocorrection de 72 heures est nouvelle depuis mars 2026 -- vérifiez que votre équipe de facturation connaît la règle actuelle plutôt qu''une hypothèse plus ancienne, plus stricte ou plus souple.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Gestion des interruptions et base légale', '[["Solution de repli hors ligne", "Les factures émises pendant une interruption confirmée du système doivent être téléversées dans les 24 heures suivant le rétablissement"], ["Base légale", "Loi sur la taxe sur les ventes de 1990, articles 3(9A) et 40C ; règles de la taxe sur les ventes de 2006, chapitre XIV"], ["Cadre de sanctions", "Loi sur la taxe sur les ventes de 1990, article 33"], ["Conséquence d''un défaut de dédouanement", "La facture est juridiquement invalide ; l''acheteur ne peut pas réclamer de crédit de taxe en amont sur celle-ci"]]', 'La fenêtre de 24 heures pour le téléversement hors ligne est destinée aux interruptions réelles et confirmées -- la posture de contrôle de la FBR la considère comme une exception étroite, non comme une solution de contournement habituelle pour une intégration lente.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux de dédouanement', 'Une facture suit cette séquence sous le système de facturation numérique de la FBR -- la validation de la FBR intervient avant que la facture soit juridiquement valable, et non après :', 'Il s''agit d''un véritable modèle de dédouanement : une facture n''a aucun effet juridique -- et ne peut justifier le crédit de taxe en amont de l''acheteur -- tant que la FBR n''a pas renvoyé un numéro de facture et un code QR valides.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Le vendeur génère la facture au format JSON' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'La facture est soumise via API, un intégrateur agréé, ou PRAL' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'La FBR valide la facture en temps réel' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'La FBR renvoie un numéro de facture unique et un code QR' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'La facture est juridiquement valable et remise à l''acheteur -- ce n''est qu''à partir de ce moment qu''elle peut justifier le crédit de taxe en amont de l''acheteur' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Pakistan' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Ce que la loi exige', '[["SRO 28(I)/2024", "Projet pilote du secteur FMCG (1er février 2024) -- l''origine de l''obligation"], ["SRO 69(I)/2025", "Cadre d''agrément et d''intégration du chapitre XIV (29 janvier 2025) -- fondateur, sans extension du champ d''application"], ["SRO 709(I)/2025", "Étendu à toutes les personnes enregistrées, morales et non morales (22 avril 2025), avec deux prorogations ultérieures d''un mois"], ["SRO 1852(I)/2025", "Calendrier définitif en vigueur : vagues les 1er nov., 15 nov., 1er déc. et 31 déc. 2025 (24 septembre 2025)"]]', 'Il s''agit du calendrier légal, pas de la réalité de la conformité -- voir la carte suivante pour savoir comment l''adoption réelle se compare effectivement à ce calendrier.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Où en est réellement la conformité', NULL, NULL, 'Malgré l''échéance formelle du 31 décembre 2025, la conformité réelle a pris un retard considérable. Le membre de la FBR chargé de la transformation stratégique, le Dr Hamid Ateeq Sarwar, a déclaré directement que seul environ un tiers des contribuables enregistrés émettait des factures numériques en direct fin mars 2026. Même selon l''indicateur plus ancien et plus restreint des points de vente (TPV) de niveau 1, 27 à 32 % des quelque 37 000 succursales de détail intégrées restaient déconnectées en juin 2026. La FBR n''a engagé un contrôle sérieux -- procédures de sanction contre les importateurs, suspension d''enregistrement, retrait du canal vert douanier -- qu''à compter du 1er juillet 2026, visant une adoption complète pour le 31 juillet 2026. À la date des recherches les plus récentes (5 août 2026), rien ne confirme dans un sens ou dans l''autre si cet objectif a réellement été atteint. Considérez l''obligation comme légalement achevée mais encore en train de converger, dans la pratique, vers une conformité complète, et non comme un fait acquis sur le terrain.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '⚠️ La non-intégration entraîne la sanction la plus sévère', NULL, NULL, 'En vertu de l''article 33, point 24, de la loi sur la taxe sur les ventes de 1990, la non-intégration à des fins de surveillance ou de suivi entraîne une amende de 500 000 Rs ou 200 % de la taxe concernée, selon le montant le plus élevé, avec une responsabilité pénale facultative pouvant aller jusqu''à 2 ans d''emprisonnement ou une amende pouvant atteindre 2 000 000 Rs. Il s''agit de la plus importante exposition financière unique dans le cadre de sanctions relatif à la facturation électronique au Pakistan.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🔒 Un défaut d''enregistrement peut entraîner la mise sous scellés des locaux', NULL, NULL, 'L''article 33, point 25, fixe une sanction pouvant atteindre 1 000 000 Rs pour absence totale d''enregistrement ou d''intégration, avec la conséquence supplémentaire que la FBR peut mettre sous scellés les locaux d''une entreprise si le manquement persiste 6 mois après l''imposition de la sanction. Le point 25AA (ajouté par la loi de finances 2024) applique la même logique aux intégrateurs agréés eux-mêmes : un intégrateur qui ne parvient pas à intégrer une personne enregistrée s''expose à 1 000 000 Rs ou à 1 % de la valeur des ventes dissimulées, selon le montant le plus élevé.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '📈 Récidive et champ d''application croissant de l''obligation', NULL, NULL, 'L''article 33(21) double la sanction applicable en cas de récidive, et la loi de finances 2025 a étendu ces dispositions de contrôle des seuls détaillants de niveau 1 à l''ensemble des personnes enregistrées -- un véritable élargissement de leur champ d''application. Au-delà des amendes, la non-conformité peut entraîner la mise sous scellés des locaux, la suspension ou l''inscription sur liste noire de l''enregistrement à la taxe sur les ventes, le retrait du canal vert douanier pour les importateurs (un nouveau levier introduit avec l''offensive du 1er juillet 2026), et des poursuites pénales en cas de fraude.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'penalties_related' AND cd.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '❓ Une échelle de sanctions souvent citée ne tient pas la route', NULL, NULL, 'Certains contenus de fournisseurs et de conseillers font circuler une échelle de sanctions croissante et bien nette de « 500 000 Rs / 1 million Rs / 2 millions Rs / 3 millions Rs » pour non-conformité en matière de facturation électronique. Cet ensemble de chiffres n''a pas pu être rattaché à une disposition légale unique et ressemble davantage à une confusion ou à une attribution erronée qu''à une lecture précise de la loi. Les lignes de sanctions ci-dessous reflètent ce que disent réellement les dispositions sourcées de l''article 33 -- utilisez-les, et non l''échelle de chiffres ronds, pour évaluer l''exposition réelle.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Pakistan' AND cd.section = 'penalties_related' AND cd.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Non-intégration à des fins de surveillance/suivi (article 33, point 24)', '500 000 Rs ou 200 % de la taxe concernée, selon le montant le plus élevé ; emprisonnement facultatif jusqu''à 2 ans ou amende jusqu''à 2 000 000 Rs', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Pakistan' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Absence totale d''enregistrement ou d''intégration (article 33, point 25)', 'Jusqu''à 1 000 000 Rs ; les locaux peuvent être mis sous scellés si le manquement persiste 6 mois après la sanction', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Pakistan' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Un intégrateur agréé ne parvient pas à intégrer une personne enregistrée (article 33, point 25AA, ajouté par la loi de finances 2024)', '1 000 000 Rs ou 1 % de la valeur des ventes dissimulées, selon le montant le plus élevé', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Pakistan' AND pr.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez votre statut d''enregistrement et quelle vague de la SRO 1852(I)/2025 s''applique à vous', 'Vérifiez si votre entreprise est une société cotée, un importateur, réalise un chiffre d''affaires supérieur à 1 milliard de roupies, fournit des entités gouvernementales, ou relève de l''une des vagues ultérieures -- la vague à laquelle vous appartenez détermine le moment où votre obligation a débuté.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Choisissez une voie d''intégration : API directe, intégrateur agréé, ou PRAL', 'PRAL (Pakistan Revenue Automation Limited) propose une option d''intégration gratuite -- pesez-la face à un intégrateur agréé ou à une construction API directe selon vos systèmes existants et votre volume.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Configurez votre système de facturation pour générer du JSON et le soumettre à une validation FBR en temps réel', 'Vérifiez que votre logiciel de facturation produit effectivement une charge JSON conforme et appelle l''API de facturation numérique de la FBR, plutôt que de s''appuyer sur un processus manuel ou par lots.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Considérez le numéro de facture et le code QR renvoyés par la FBR comme le point de validité juridique', 'Une facture sans le numéro et le code QR renvoyés par la FBR n''est pas juridiquement valable et ne peut justifier le crédit de taxe en amont de l''acheteur -- ne considérez pas la simple soumission comme un achèvement.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Mettez en place un véritable processus de repli en cas de panne de 24 heures et d''autocorrection de 72 heures', 'Limitez strictement les deux aux véritables interruptions du système et aux besoins de correction réels -- la posture de contrôle de la FBR traite un recours habituel à l''un ou l''autre comme un signal d''alerte de conformité, non comme une habitude sans risque.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Suivez le projet de SRO 288(I)/2026 si votre entreprise est un restaurant, une clinique, un salon, une messagerie, un cabinet comptable, une école, une salle de sport ou similaire', 'Le projet n''est pas encore juridiquement contraignant -- surveillez l''arrêté général de l''impôt sur le revenu à venir qui le ferait réellement entrer en vigueur, plutôt que d''agir comme si le projet lui-même était déjà applicable aujourd''hui.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Pakistan' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'FBR Digital Invoicing — assistance technique, orientation à l''intégration et accès au portail IRIS' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Pakistan' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Federal Board of Revenue (FBR) — site général, SRO et notifications réglementaires' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Pakistan' AND pt.sort_order = 1;
